const html: string = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n<title>NidhiNetra — Pre-Sanction Work Intelligence Form</title>\n<style>\n:root{\n  --navy:#0b1f3a;\n  --blue:#1f5eff;\n  --blue2:#eaf0ff;\n  --ink:#1f2937;\n  --muted:#64748b;\n  --line:#cbd5e1;\n  --soft:#f8fafc;\n  --green:#177245;\n  --amber:#a15c00;\n  --red:#b42318;\n  --purple:#6d42c7;\n  --cost:#e8f7ee;\n  --dup:#fff0f2;\n  --time:#fff7d8;\n  --site:#eaf6ff;\n}\n*{box-sizing:border-box}\nbody{margin:0;background:#eef2f7;color:var(--ink);font:14px/1.35 Arial, Helvetica, sans-serif}\n.shell{max-width:1320px;margin:24px auto;padding:0 16px 48px}\n.paper{background:#fff;border:1px solid #d7dee8;box-shadow:0 8px 28px rgba(15,23,42,.08)}\n.header{border-top:7px solid var(--navy);padding:20px 24px 14px;border-bottom:1px solid var(--line)}\n.brandrow{display:flex;align-items:flex-start;justify-content:space-between;gap:24px}\n.brand h1{margin:0;color:var(--navy);font-size:24px;letter-spacing:.2px}\n.brand p{margin:4px 0 0;color:var(--muted);font-size:12.5px}\n.meta{min-width:330px;border:1px solid var(--line);display:grid;grid-template-columns:1fr 1fr;background:#fff}\n.meta div{padding:8px 10px;border-right:1px solid var(--line);border-bottom:1px solid var(--line)}\n.meta div:nth-child(2n){border-right:0}.meta div:nth-last-child(-n+2){border-bottom:0}\n.meta b{display:block;font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.5px;margin-bottom:2px}\n.meta span{font-weight:700;color:var(--navy)}\n.notice{margin-top:12px;padding:10px 12px;border-left:4px solid var(--blue);background:#f6f8ff;color:#334155;font-size:12px}\n.toolbar{display:flex;gap:8px;flex-wrap:wrap;padding:12px 24px;border-bottom:1px solid var(--line);background:#fbfcfe;position:sticky;top:0;z-index:10}\nbutton{font:inherit;border:1px solid #b7c2d0;background:#fff;color:var(--navy);padding:8px 12px;border-radius:5px;cursor:pointer;font-weight:700}\nbutton.primary{background:var(--navy);color:#fff;border-color:var(--navy)}\nbutton.blue{background:var(--blue);color:#fff;border-color:var(--blue)}\nbutton.danger{color:var(--red)}\n.statuspill{margin-left:auto;display:flex;align-items:center;gap:8px;padding:7px 10px;border:1px solid var(--line);background:#fff;border-radius:5px;font-size:12px}\n.statusdot{width:8px;height:8px;border-radius:50%;background:#f59e0b}\n.formbody{padding:8px 24px 24px}\n.section{border:1px solid var(--line);margin-top:16px}\n.sectionhead{display:flex;align-items:center;justify-content:space-between;gap:10px;background:var(--navy);color:#fff;padding:10px 12px}\n.sectionhead h2{margin:0;font-size:14px;letter-spacing:.2px}.sectionhead small{opacity:.82}\n.sectionbody{padding:12px}\n.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:10px}\n.field{grid-column:span 3}.field.w2{grid-column:span 2}.field.w4{grid-column:span 4}.field.w6{grid-column:span 6}.field.w8{grid-column:span 8}.field.w9{grid-column:span 9}.field.w12{grid-column:span 12}\nlabel{display:block;font-weight:700;font-size:11px;color:#334155;margin-bottom:4px}\nlabel .req{color:var(--red)}\ninput,select,textarea{width:100%;border:1px solid #b7c2d0;background:#fff;border-radius:3px;padding:8px 9px;font:inherit;color:#111827;min-height:36px}\ntextarea{min-height:72px;resize:vertical}\ninput:focus,select:focus,textarea:focus{outline:2px solid #cbd8ff;border-color:var(--blue)}\n.help{font-size:10.5px;color:var(--muted);margin-top:3px}\n.subhead{grid-column:span 12;margin-top:4px;padding:6px 8px;background:#f1f5f9;border-left:3px solid var(--blue);font-weight:800;color:var(--navy);font-size:12px}\n.checkgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;grid-column:span 12}\n.check{display:flex;gap:7px;align-items:flex-start;border:1px solid #d8e0ea;padding:8px;background:#fff;border-radius:3px;min-height:48px}\n.check input{width:auto;min-height:0;margin-top:2px}.check span{font-size:11px}\n.agentchips{display:flex;gap:5px;flex-wrap:wrap}\n.chip{font-size:10px;font-weight:800;padding:3px 6px;border-radius:999px;color:#263238;border:1px solid transparent}\n.chip.cost{background:var(--cost);border-color:#b7e1c6}.chip.dup{background:var(--dup);border-color:#f0c3ca}.chip.time{background:var(--time);border-color:#eadb8b}.chip.site{background:var(--site);border-color:#bdddf2}\n.locationbox{grid-column:span 12;border:1px solid #a9bdd8;background:#f8fbff;padding:10px}\n.locationrow{display:grid;grid-template-columns:1fr 1fr 1fr 1fr auto;gap:8px;align-items:end;margin-top:8px}\n.locationrow .field{grid-column:auto}\n.locbtn{white-space:nowrap;height:36px}\n.tablewrap{grid-column:span 12;overflow:auto;border:1px solid var(--line)}\ntable{width:100%;border-collapse:collapse;min-width:980px;background:#fff}\nth,td{border-right:1px solid var(--line);border-bottom:1px solid var(--line);padding:6px;vertical-align:top}\nth:last-child,td:last-child{border-right:0}tr:last-child td{border-bottom:0}\nth{background:#eef3f8;color:var(--navy);font-size:10.5px;text-align:left}\ntd input,td select{min-height:32px;padding:5px 6px;border-color:#c7d0dc}\n.money{text-align:right}\n.totalbar{grid-column:span 12;display:flex;justify-content:flex-end;gap:16px;align-items:center;padding:10px;background:#f8fafc;border:1px solid var(--line);border-top:0}\n.totalbar strong{font-size:15px;color:var(--navy)}\n.dynamic{grid-column:span 12;border:1px dashed #94a3b8;background:#fcfdff;padding:10px}\n.dynamic.hidden{display:none}\n.readiness{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}\n.readycard{border:1px solid var(--line);padding:10px;border-top:4px solid var(--navy);background:#fff}\n.readycard b{display:block;color:var(--navy);margin-bottom:4px}.readycard span{font-size:11px;color:var(--muted)}\n.signature{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:12px}\n.sigbox{min-height:110px;border:1px solid var(--line);padding:10px;background:#fff}.sigbox b{display:block;color:var(--navy);margin-bottom:8px}\n.inline{display:flex;gap:8px;align-items:center}.inline input[type=checkbox]{width:auto;min-height:0}\n.footer{padding:14px 24px;border-top:1px solid var(--line);font-size:10.5px;color:var(--muted);display:flex;justify-content:space-between;gap:20px}\n.alert{display:none;margin:12px 24px 0;padding:10px 12px;border:1px solid #f1c5c5;background:#fff6f6;color:#8a1c1c}.alert.show{display:block}\n.ok{border-color:#b8dfc7;background:#f2fbf5;color:#14532d}\n.smallbtn{padding:5px 8px;font-size:11px}\n@media(max-width:900px){.brandrow{display:block}.meta{margin-top:14px;min-width:0}.field,.field.w2,.field.w4,.field.w6,.field.w8,.field.w9{grid-column:span 12}.checkgrid{grid-template-columns:1fr 1fr}.locationrow{grid-template-columns:1fr 1fr}.readiness{grid-template-columns:1fr 1fr}.signature{grid-template-columns:1fr}.statuspill{margin-left:0}.toolbar{position:static}}\n@media(max-width:560px){\n  .shell{margin:0;padding:0}.paper{border-left:0;border-right:0}\n  .header{padding:14px 12px 10px}.brand h1{font-size:19px}.meta{grid-template-columns:1fr 1fr}\n  .toolbar{padding:10px 12px}.alert{margin:10px 12px 0}.formbody{padding:4px 8px 14px}\n  .sectionhead{flex-wrap:wrap}.sectionbody{padding:10px 8px}.footer{display:block;padding:12px}\n  .checkgrid,.readiness,.locationrow{grid-template-columns:1fr}.locbtn{width:100%}.readycard{overflow-wrap:anywhere}\n  .totalbar{flex-wrap:wrap;justify-content:space-between}\n  .tablewrap{overflow:visible;border:0}\n  .tablewrap table{min-width:0!important;background:transparent}\n  .tablewrap thead{display:none}\n  .tablewrap table,.tablewrap tbody,.tablewrap tr,.tablewrap td{display:block;width:100%}\n  .tablewrap tr{border:1px solid var(--line);margin-bottom:10px;background:#fff}\n  .tablewrap td{border-right:0;display:grid;grid-template-columns:36% minmax(0,1fr);gap:8px;align-items:center;padding:5px 8px}\n  .tablewrap td::before{content:attr(data-label);font-size:10.5px;font-weight:700;color:var(--navy)}\n  .tablewrap tr:last-child td{border-bottom:1px solid var(--line)}.tablewrap tr td:last-child{border-bottom:0}\n}\n@media print{body{background:#fff}.shell{margin:0;max-width:none;padding:0}.paper{box-shadow:none;border:0}.toolbar,.alert,.locbtn,.row-actions,.no-print{display:none!important}.section{break-inside:avoid}.sectionbody{padding:9px}.header{padding-top:10px}.formbody{padding:4px 14px 14px}.footer{padding:10px 14px}.sectionhead{background:#dfe8f4!important;color:#0b1f3a!important;-webkit-print-color-adjust:exact;print-color-adjust:exact}.field{break-inside:avoid}}\n</style>\n</head>\n<body>\n<div class=\"shell\">\n<div class=\"paper\">\n  <div class=\"header\">\n    <div class=\"brandrow\">\n      <div class=\"brand\">\n        <h1>NidhiNetra — Pre‑Sanction Work Intelligence Form</h1>\n        <p>Structured evidence form for MPLADS work scrutiny, technical estimation and agent-ready anomaly screening</p>\n      </div>\n      <div class=\"meta\">\n        <div><b>Form Version</b><span>PSWIF v1.1</span></div>\n        <div><b>Status</b><span id=\"headerStatus\">DRAFT</span></div>\n        <div><b>Work ID</b><span id=\"workIdDisplay\">Auto on save</span></div>\n        <div><b>Data Lock</b><span id=\"lockStatus\">Not locked</span></div>\n      </div>\n    </div>\n    <div class=\"notice\"><b>Design principle:</b> collect facts once, at sanction stage, in machine-readable form. NidhiNetra should verify facts against official rates, map geometry, previous works, dates and later site evidence — not infer missing project details from thin records.</div>\n  </div>\n\n  <div class=\"toolbar no-print\">\n    <button class=\"primary\" type=\"button\" onclick=\"saveDraft()\">Save Draft</button>\n    <button type=\"button\" onclick=\"loadDraft()\">Load Draft</button>\n    <button type=\"button\" onclick=\"validateForm()\">Validate Required Data</button>\n    <button class=\"blue\" type=\"button\" onclick=\"downloadJSON()\">Export Structured JSON</button>\n    <button type=\"button\" onclick=\"window.print()\">Print / Save PDF</button>\n    <button class=\"danger\" type=\"button\" onclick=\"clearDraft()\">Clear</button>\n    <div class=\"statuspill\"><span class=\"statusdot\" id=\"statusDot\"></span><span id=\"readinessText\">Agent data readiness not checked</span></div>\n  </div>\n  <div class=\"alert\" id=\"alertBox\"></div>\n\n  <form id=\"nidhinetraForm\" class=\"formbody\" onsubmit=\"return false\">\n\n    <section class=\"section\">\n      <div class=\"sectionhead\"><h2>A. Recommendation & Administrative Identity</h2><div class=\"agentchips\"><span class=\"chip time\">TIME / RULES</span><span class=\"chip dup\">DUPLICATE</span></div></div>\n      <div class=\"sectionbody grid\">\n        <div class=\"field w4\"><label>eSAKSHI / Recommendation Reference No. <span class=\"req\">*</span></label><input name=\"recommendation_ref\" required></div>\n        <div class=\"field w4\"><label>Date MP Recommendation Submitted <span class=\"req\">*</span></label><input type=\"date\" name=\"mp_recommendation_date\" required></div>\n        <div class=\"field w4\"><label>Date Received by Implementing District Authority <span class=\"req\">*</span></label><input type=\"date\" name=\"ida_received_date\" required></div>\n        <div class=\"field w4\"><label>Member of Parliament Name <span class=\"req\">*</span></label><input name=\"mp_name\" required></div>\n        <div class=\"field w2\"><label>House</label><select name=\"mp_house\"><option value=\"\">Select</option><option>Lok Sabha</option><option>Rajya Sabha</option><option>Nominated</option></select></div>\n        <div class=\"field w3\"><label>Constituency / State</label><input name=\"constituency_state\"></div>\n        <div class=\"field w3\"><label>Financial Year <span class=\"req\">*</span></label><input name=\"financial_year\" placeholder=\"2026-27\" required></div>\n        <div class=\"field w4\"><label>Nodal District Authority</label><input name=\"nodal_district_authority\"></div>\n        <div class=\"field w4\"><label>Implementing District Authority (Sanctioning Authority) <span class=\"req\">*</span></label><input name=\"implementing_district_authority\" required></div>\n        <div class=\"field w4\"><label>Implementing Agency proposed/selected <span class=\"req\">*</span></label><input name=\"implementing_agency\" required></div>\n        <div class=\"field w4\"><label>Recommendation Jurisdiction / Special Case</label><select name=\"recommendation_jurisdiction\"><option>Normal constituency / permitted State jurisdiction</option><option>Permitted work outside usual jurisdiction</option><option>Calamity-related recommendation</option><option>Other special case</option></select></div>\n        <div class=\"field w4\"><label>Special-case approval / ceiling reference</label><input name=\"special_case_ref\"></div>\n        <div class=\"field w4\"><label>Calamity / Special Context, if applicable</label><input name=\"calamity_context\"></div>\n        <div class=\"field w4\"><label>Preparing Officer / Engineer</label><input name=\"preparing_officer\"></div>\n        <div class=\"field w4\"><label>Designation & Department</label><input name=\"preparing_designation\"></div>\n        <div class=\"field w4\"><label>Official Email / Mobile</label><input name=\"official_contact\"></div>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <div class=\"sectionhead\"><h2>B. Work Identity, Classification & Scope</h2><div class=\"agentchips\"><span class=\"chip cost\">COST</span><span class=\"chip dup\">DUPLICATE</span><span class=\"chip time\">TIME / RULES</span><span class=\"chip site\">SITE</span></div></div>\n      <div class=\"sectionbody grid\">\n        <div class=\"field w8\"><label>Recommended Work Title <span class=\"req\">*</span></label><input name=\"work_title\" required placeholder=\"Use a specific asset + location title, not a generic description\"></div>\n        <div class=\"field w4\"><label>MPLADS Sector / Guideline Category <span class=\"req\">*</span></label>\n          <select name=\"sector\" required><option value=\"\">Select</option><option>Public & community building</option><option>Public conveniences / safety / security</option><option>Education</option><option>Public health</option><option>Drinking water & sanitation</option><option>Irrigation / drainage / flood control</option><option>Animal husbandry / dairy / fisheries</option><option>Agriculture & farmer welfare</option><option>Energy supply / distribution</option><option>Railways / roads / bridges / pathways</option><option>Environment / forest / natural resources</option><option>Public recreation / sports / parks</option><option>Other public utility work</option></select>\n        </div>\n        <div class=\"field w4\"><label>Indicative-list Status</label><select name=\"indicative_list_status\"><option>Listed / clearly covered by permissible category</option><option>New public-utility work not explicitly listed</option><option>Needs eligibility clarification</option></select></div>\n        <div class=\"field w4\"><label>If new/unlisted: approval / examination reference</label><input name=\"new_work_eligibility_ref\"></div>\n        <div class=\"field w4\"><label>Domain-specific mandatory agency?</label><select name=\"mandatory_domain_agency\"><option>No / not applicable</option><option>Yes — Railways</option><option>Yes — Archaeological Survey / protected monument</option><option>Yes — other Central/State domain agency</option></select></div>\n        <div class=\"field w4\"><label>Technical Work Type <span class=\"req\">*</span></label>\n          <select name=\"work_type\" id=\"workType\" required onchange=\"showDynamicType()\"><option value=\"\">Select</option><option value=\"road\">Road / Pathway / Bridge / Culvert</option><option value=\"building\">Building / Hall / Classroom / Health Facility</option><option value=\"water\">Water Supply / Sanitation</option><option value=\"drainage\">Drainage / Irrigation / Flood-control</option><option value=\"energy\">Street-light / Solar / Energy Asset</option><option value=\"equipment\">Movable Equipment / Public-use System</option><option value=\"park\">Park / Sports / Public Recreation</option><option value=\"other\">Other Durable Public Asset</option></select>\n        </div>\n        <div class=\"field w4\"><label>Nature of Work <span class=\"req\">*</span></label>\n          <select name=\"work_nature\" required><option value=\"\">Select</option><option>New asset</option><option>Extension / additional component</option><option>Continuation / next phase</option><option>Repair / renovation</option><option>Reconstruction / rebuild</option><option>Replacement of movable asset</option></select>\n        </div>\n        <div class=\"field w4\"><label>Public/User Agency that will own/custody asset <span class=\"req\">*</span></label><input name=\"user_agency\" required></div>\n        <div class=\"field w6\"><label>Exact Scope of Work <span class=\"req\">*</span></label><textarea name=\"scope_of_work\" required placeholder=\"Define what is included, quantities/extent, and explicit exclusions.\"></textarea></div>\n        <div class=\"field w6\"><label>Public Need / Intended Use</label><textarea name=\"public_need\"></textarea></div>\n        <div class=\"field w4\"><label>Asset Access</label><select name=\"public_access\"><option value=\"\">Select</option><option>Unrestricted public/community access</option><option>Controlled access for public service</option><option>Restricted / beneficiary-specific</option></select></div>\n        <div class=\"field w4\"><label>Beneficiary / Institution Type</label><select name=\"beneficiary_type\" id=\"beneficiaryType\" onchange=\"toggleTrustFields()\"><option value=\"\">Select</option><option>Government / Local Government</option><option>Government-controlled institution</option><option>Registered Society / Trust</option><option>Cooperative Society</option><option>Bar Association</option><option>Other</option></select></div>\n        <div class=\"field w4\"><label>Priority Area Tag</label><select name=\"priority_area\"><option>General</option><option>SC-predominant area</option><option>ST-predominant area</option><option>SC & ST-predominant area</option></select></div>\n\n        <div class=\"dynamic hidden\" id=\"trustFields\">\n          <div class=\"grid\">\n            <div class=\"field w4\"><label>Registration No.</label><input name=\"trust_registration_no\"></div>\n            <div class=\"field w4\"><label>Registration / Activity Start Date</label><input type=\"date\" name=\"trust_start_date\"></div>\n            <div class=\"field w4\"><label>NITI Aayog Darpan Unique ID</label><input name=\"darpan_id\"></div>\n            <div class=\"field w6\"><label>Land Ownership / Long-term Lease Details</label><input name=\"trust_land_details\"></div>\n            <div class=\"field w6\"><label>Prior MPLADS Assistance to this Entity (IDs & amounts)</label><input name=\"trust_prior_assistance\"></div>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <div class=\"sectionhead\"><h2>C. Site, Land & Geospatial Capture</h2><div class=\"agentchips\"><span class=\"chip dup\">DUPLICATE</span><span class=\"chip cost\">COST</span><span class=\"chip site\">SITE</span><span class=\"chip time\">RULES</span></div></div>\n      <div class=\"sectionbody grid\">\n        <div class=\"field w3\"><label>State / UT <span class=\"req\">*</span></label><input name=\"state\" required></div>\n        <div class=\"field w3\"><label>District <span class=\"req\">*</span></label><input name=\"district\" required></div>\n        <div class=\"field w3\"><label>Block / Tehsil / ULB</label><input name=\"block_tehsil\"></div>\n        <div class=\"field w3\"><label>Village / Ward / Locality <span class=\"req\">*</span></label><input name=\"village_ward\" required></div>\n        <div class=\"field w6\"><label>Site Address / Landmark <span class=\"req\">*</span></label><input name=\"site_address\" required></div>\n        <div class=\"field w3\"><label>Land Parcel / Survey / Khasra No.</label><input name=\"land_parcel_no\"></div>\n        <div class=\"field w3\"><label>PIN Code</label><input name=\"pincode\"></div>\n        <div class=\"field w4\"><label>Land Ownership <span class=\"req\">*</span></label><select name=\"land_ownership\" required><option value=\"\">Select</option><option>Central Government</option><option>State / UT Government</option><option>Local Government / Panchayat / ULB</option><option>Government-controlled institution</option><option>Eligible Society/Trust long-term lease</option><option>Private</option><option>Religious body / religious land</option><option>Unknown / disputed</option></select></div>\n        <div class=\"field w4\"><label>Land Title / Possession Proof Reference</label><input name=\"land_proof_ref\"></div>\n        <div class=\"field w4\"><label>Site Legal Status</label><select name=\"site_legal_status\"><option value=\"\">Select</option><option>Authorized / approved</option><option>Unauthorized colony / unapproved layout</option><option>Encroachment/dispute present</option><option>Not applicable</option></select></div>\n        <div class=\"field w4\"><label>Site Geometry Type <span class=\"req\">*</span></label><select name=\"site_geometry_type\" required><option value=\"\">Select</option><option>Point asset</option><option>Linear asset / alignment</option><option>Area / polygon / campus</option><option>Multiple discrete points</option></select></div>\n        <div class=\"field w8\"><label>Footprint / Polygon / Multi-point Geometry Reference</label><input name=\"geometry_file_ref\" placeholder=\"KML / GeoJSON / drawing / coordinate-list reference for exact footprint or campus boundary\"></div>\n\n        <div class=\"locationbox\">\n          <b style=\"color:var(--navy)\">Primary Site Coordinates</b> <span class=\"help\">Capture from the device at site. Accuracy is stored so the system does not treat a poor GPS fix as exact.</span>\n          <div class=\"locationrow\">\n            <div class=\"field\"><label>Latitude <span class=\"req\">*</span></label><input id=\"lat\" name=\"latitude\" inputmode=\"decimal\" required></div>\n            <div class=\"field\"><label>Longitude <span class=\"req\">*</span></label><input id=\"lon\" name=\"longitude\" inputmode=\"decimal\" required></div>\n            <div class=\"field\"><label>GPS Accuracy (± metres)</label><input id=\"acc\" name=\"gps_accuracy\" readonly></div>\n            <div class=\"field\"><label>Captured At</label><input id=\"geoTime\" name=\"geo_timestamp\" readonly></div>\n            <button type=\"button\" class=\"blue locbtn\" onclick=\"captureGeo('primary')\">Capture Current Location</button>\n          </div>\n          <div id=\"mapLink\" class=\"help\" style=\"margin-top:6px\"></div>\n        </div>\n\n        <div class=\"locationbox\" id=\"linearGeo\" style=\"display:none\">\n          <b style=\"color:var(--navy)\">Linear Asset Geometry — Start / End Required</b>\n          <div class=\"locationrow\">\n            <div class=\"field\"><label>Start Latitude</label><input id=\"startLat\" name=\"start_lat\"></div>\n            <div class=\"field\"><label>Start Longitude</label><input id=\"startLon\" name=\"start_lon\"></div>\n            <div class=\"field\"><label>Start Accuracy</label><input id=\"startAcc\" name=\"start_accuracy\" readonly></div>\n            <div class=\"field\"><label>Start Captured</label><input id=\"startTime\" name=\"start_geo_timestamp\" readonly></div>\n            <button type=\"button\" class=\"locbtn\" onclick=\"captureGeo('start')\">Capture Start</button>\n          </div>\n          <div class=\"locationrow\">\n            <div class=\"field\"><label>End Latitude</label><input id=\"endLat\" name=\"end_lat\"></div>\n            <div class=\"field\"><label>End Longitude</label><input id=\"endLon\" name=\"end_lon\"></div>\n            <div class=\"field\"><label>End Accuracy</label><input id=\"endAcc\" name=\"end_accuracy\" readonly></div>\n            <div class=\"field\"><label>End Captured</label><input id=\"endTime\" name=\"end_geo_timestamp\" readonly></div>\n            <button type=\"button\" class=\"locbtn\" onclick=\"captureGeo('end')\">Capture End</button>\n          </div>\n          <div class=\"grid\" style=\"margin-top:8px\"><div class=\"field w8\"><label>Intermediate route / alignment reference (KML/GeoJSON/file ID)</label><input name=\"alignment_ref\"></div><div class=\"field w4\"><label>Measured / designed route length (m)</label><input type=\"number\" step=\"0.01\" name=\"route_length_m\"></div></div>\n        </div>\n\n        <div class=\"subhead\">Site-condition facts used to explain legitimate cost/time differences</div>\n        <div class=\"field w3\"><label>Terrain</label><select name=\"terrain\"><option>Plain</option><option>Rolling</option><option>Hilly / steep</option><option>Riverine / flood-prone</option><option>Coastal</option><option>Dense urban</option><option>Remote / difficult access</option><option>Other</option></select></div>\n        <div class=\"field w3\"><label>Access to Site</label><select name=\"site_access\"><option>Motorable all-weather</option><option>Narrow road / limited vehicle</option><option>Foot / manual carry required</option><option>Seasonal access</option><option>Boat / special access</option></select></div>\n        <div class=\"field w3\"><label>Nearest Motorable Access (m)</label><input type=\"number\" name=\"motorable_access_distance_m\"></div>\n        <div class=\"field w3\"><label>Material Lead Distance Basis</label><input name=\"lead_distance_basis\" placeholder=\"Quarry / depot / market source\"></div>\n        <div class=\"field w6\"><label>Known Physical Constraints</label><input name=\"physical_constraints\" placeholder=\"utilities, traffic, steep slope, waterlogging, limited working hours, etc.\"></div>\n        <div class=\"field w6\"><label>Pre-sanction site evidence reference</label><input name=\"presanction_site_evidence\" placeholder=\"Photo / survey / map / measurement file reference\"></div>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <div class=\"sectionhead\"><h2>D. Duplicate / Continuation / Split-Work Intelligence</h2><div class=\"agentchips\"><span class=\"chip dup\">DUPLICATE</span><span class=\"chip site\">SITE</span></div></div>\n      <div class=\"sectionbody grid\">\n        <div class=\"field w4\"><label>Is this part of a larger logical project / package? <span class=\"req\">*</span></label><select name=\"part_of_larger_project\" id=\"largerProject\" required onchange=\"toggleLargerProject()\"><option value=\"\">Select</option><option>No</option><option>Yes</option></select></div>\n        <div class=\"field w4\"><label>Parent / Master Project ID</label><input name=\"parent_project_id\"></div>\n        <div class=\"field w4\"><label>Full Logical Project Estimated Cost (₹)</label><input type=\"number\" step=\"0.01\" name=\"full_project_cost\"></div>\n        <div class=\"dynamic hidden\" id=\"largerProjectFields\">\n          <div class=\"grid\">\n            <div class=\"field w6\"><label>All known phase / work IDs</label><input name=\"related_phase_ids\" placeholder=\"Comma-separated IDs\"></div>\n            <div class=\"field w6\"><label>Why separate phases/packages are technically necessary</label><input name=\"phase_justification\"></div>\n            <div class=\"field w6\"><label>Whole-project geography / alignment reference</label><input name=\"whole_project_geometry_ref\"></div>\n            <div class=\"field w6\"><label>Other funding sources / departments for remaining phases</label><input name=\"other_phase_funding\"></div>\n          </div>\n        </div>\n        <div class=\"field w4\"><label>Related Existing Asset at Same Site?</label><select name=\"existing_asset_same_site\"><option>No</option><option>Yes</option><option>Unknown</option></select></div>\n        <div class=\"field w4\"><label>Prior Work ID / Asset ID</label><input name=\"prior_work_id\"></div>\n        <div class=\"field w4\"><label>Prior Work Completion Date</label><input type=\"date\" name=\"prior_completion_date\"></div>\n        <div class=\"field w6\"><label>Reason for continuation / repair / rebuild / extension</label><input name=\"repeat_reason\"></div>\n        <div class=\"field w6\"><label>Condition evidence / engineering assessment reference</label><input name=\"condition_evidence_ref\"></div>\n        <div class=\"field w6\"><label>Known similar MPLADS / Govt work within or adjacent to this site</label><input name=\"known_nearby_work_ids\" placeholder=\"IDs if known; system will independently search map records\"></div>\n        <div class=\"field w6\"><label>Relationship to nearby work</label><select name=\"nearby_work_relationship\"><option value=\"\">Select</option><option>None known</option><option>Same asset, separate phase</option><option>Different asset at same campus/site</option><option>Rebuild / replacement</option><option>Parallel / adjacent infrastructure</option><option>Unknown</option></select></div>\n        <div class=\"field w6\"><label>Known recommendations/sanctions for same logical scope in last 90 days</label><input name=\"same_scope_recent_ids\"></div>\n        <div class=\"field w6\"><label>Agency Declaration on overlap</label><textarea name=\"overlap_declaration\" placeholder=\"Declare known overlap/continuation relationships. NidhiNetra verifies independently.\"></textarea></div>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <div class=\"sectionhead\"><h2>E. Technical Dimensions & Measurable Scope</h2><div class=\"agentchips\"><span class=\"chip cost\">COST</span><span class=\"chip time\">TIME</span><span class=\"chip site\">SITE</span></div></div>\n      <div class=\"sectionbody grid\">\n        <div class=\"dynamic\" id=\"defaultTypeHelp\"><b>Select a Technical Work Type in Section B.</b> The form will show the measurements the Cost and Time agents need for that asset type.</div>\n\n        <div class=\"dynamic hidden\" id=\"type_road\"><div class=\"grid\">\n          <div class=\"field w3\"><label>Road / Asset Subtype</label><select name=\"road_subtype\"><option>CC road</option><option>Bituminous road</option><option>Paver block road</option><option>Gravel / WBM</option><option>Pathway</option><option>Bridge</option><option>Culvert</option><option>Other</option></select></div>\n          <div class=\"field w3\"><label>Designed Length (m)</label><input type=\"number\" step=\"0.01\" name=\"road_length_m\"></div>\n          <div class=\"field w3\"><label>Carriageway / Paved Width (m)</label><input type=\"number\" step=\"0.01\" name=\"road_width_m\"></div>\n          <div class=\"field w3\"><label>Total Formation Width (m)</label><input type=\"number\" step=\"0.01\" name=\"formation_width_m\"></div>\n          <div class=\"field w3\"><label>Pavement / Slab Thickness (mm)</label><input type=\"number\" name=\"pavement_thickness_mm\"></div>\n          <div class=\"field w3\"><label>Sub-base Thickness (mm)</label><input type=\"number\" name=\"subbase_thickness_mm\"></div>\n          <div class=\"field w3\"><label>Base Course Thickness (mm)</label><input type=\"number\" name=\"base_thickness_mm\"></div>\n          <div class=\"field w3\"><label>Shoulder Width each side (m)</label><input type=\"number\" step=\"0.01\" name=\"shoulder_width_m\"></div>\n          <div class=\"field w3\"><label>Drain Length (m)</label><input type=\"number\" step=\"0.01\" name=\"road_drain_length_m\"></div>\n          <div class=\"field w3\"><label>Culverts / Cross-drainage count</label><input type=\"number\" name=\"culvert_count\"></div>\n          <div class=\"field w3\"><label>Design Grade / Concrete / Mix</label><input name=\"road_material_grade\"></div>\n          <div class=\"field w3\"><label>Existing Road Condition</label><select name=\"existing_road_condition\"><option>New alignment</option><option>Earthen</option><option>Damaged paved road</option><option>Existing base retained</option><option>Other</option></select></div>\n          <div class=\"field w6\"><label>Layer composition / specification</label><input name=\"road_layer_spec\" placeholder=\"e.g., subgrade + GSB + WMM + PQC / BC etc.\"></div>\n          <div class=\"field w6\"><label>Traffic / utility / drainage constraints</label><input name=\"road_constraints\"></div>\n        </div></div>\n\n        <div class=\"dynamic hidden\" id=\"type_building\"><div class=\"grid\">\n          <div class=\"field w3\"><label>Site Area (m²)</label><input type=\"number\" step=\"0.01\" name=\"building_site_area\"></div>\n          <div class=\"field w3\"><label>Total Built-up Area (m²)</label><input type=\"number\" step=\"0.01\" name=\"builtup_area\"></div>\n          <div class=\"field w3\"><label>No. of Floors</label><input type=\"number\" name=\"floors\"></div>\n          <div class=\"field w3\"><label>No. of Rooms / Functional Spaces</label><input type=\"number\" name=\"rooms\"></div>\n          <div class=\"field w3\"><label>Structural System</label><select name=\"structure_type\"><option>RCC framed</option><option>Load-bearing masonry</option><option>Steel / prefab</option><option>Mixed</option><option>Other</option></select></div>\n          <div class=\"field w3\"><label>Foundation Type</label><input name=\"foundation_type\"></div>\n          <div class=\"field w3\"><label>Roof Type</label><input name=\"roof_type\"></div>\n          <div class=\"field w3\"><label>Typical Floor Height (m)</label><input type=\"number\" step=\"0.01\" name=\"floor_height\"></div>\n          <div class=\"field w4\"><label>Sanitary / Plumbing Scope</label><input name=\"plumbing_scope\"></div>\n          <div class=\"field w4\"><label>Electrical Scope</label><input name=\"electrical_scope\"></div>\n          <div class=\"field w4\"><label>External Works / Boundary / Drainage</label><input name=\"external_works_scope\"></div>\n          <div class=\"field w6\"><label>Finish / specification level</label><input name=\"finish_spec\"></div>\n          <div class=\"field w6\"><label>Accessibility provisions</label><input name=\"accessibility_provisions\" placeholder=\"Ramp, accessible toilet, handrails, etc.\"></div>\n        </div></div>\n\n        <div class=\"dynamic hidden\" id=\"type_water\"><div class=\"grid\">\n          <div class=\"field w3\"><label>System Type</label><select name=\"water_system_type\"><option>Overhead tank</option><option>Ground reservoir</option><option>Pipeline</option><option>Water treatment</option><option>Public tap / standpost</option><option>Borewell / source</option><option>Sanitation asset</option><option>Other</option></select></div>\n          <div class=\"field w3\"><label>Storage Capacity (kL)</label><input type=\"number\" step=\"0.01\" name=\"storage_capacity_kl\"></div>\n          <div class=\"field w3\"><label>Pipeline Length (m)</label><input type=\"number\" step=\"0.01\" name=\"pipeline_length_m\"></div>\n          <div class=\"field w3\"><label>Pipeline Diameter (mm)</label><input type=\"number\" name=\"pipeline_diameter_mm\"></div>\n          <div class=\"field w3\"><label>Pipe Material / Class</label><input name=\"pipe_material\"></div>\n          <div class=\"field w3\"><label>Pump Capacity / Head</label><input name=\"pump_capacity_head\"></div>\n          <div class=\"field w3\"><label>Treatment Capacity (KLD)</label><input type=\"number\" step=\"0.01\" name=\"treatment_capacity_kld\"></div>\n          <div class=\"field w3\"><label>Expected Connections / Users</label><input type=\"number\" name=\"connections_users\"></div>\n          <div class=\"field w6\"><label>Source / intake details</label><input name=\"water_source_details\"></div>\n          <div class=\"field w6\"><label>Testing / quality specification</label><input name=\"water_quality_spec\"></div>\n        </div></div>\n\n        <div class=\"dynamic hidden\" id=\"type_drainage\"><div class=\"grid\">\n          <div class=\"field w3\"><label>Drain / Canal Type</label><input name=\"drain_type\"></div>\n          <div class=\"field w3\"><label>Length (m)</label><input type=\"number\" step=\"0.01\" name=\"drain_length_m\"></div>\n          <div class=\"field w3\"><label>Internal Width (m)</label><input type=\"number\" step=\"0.01\" name=\"drain_width_m\"></div>\n          <div class=\"field w3\"><label>Depth (m)</label><input type=\"number\" step=\"0.01\" name=\"drain_depth_m\"></div>\n          <div class=\"field w3\"><label>Lining / Material</label><input name=\"drain_lining\"></div>\n          <div class=\"field w3\"><label>Crossings / Culverts</label><input type=\"number\" name=\"drain_crossings\"></div>\n          <div class=\"field w3\"><label>Catchment / Service Area</label><input name=\"catchment_area\"></div>\n          <div class=\"field w3\"><label>Design Discharge</label><input name=\"design_discharge\"></div>\n          <div class=\"field w6\"><label>Outfall / discharge point coordinates or reference</label><input name=\"outfall_ref\"></div>\n          <div class=\"field w6\"><label>Flood / waterlogging design basis</label><input name=\"flood_design_basis\"></div>\n        </div></div>\n\n        <div class=\"dynamic hidden\" id=\"type_energy\"><div class=\"grid\">\n          <div class=\"field w3\"><label>Asset Type</label><select name=\"energy_asset_type\"><option>Street lights</option><option>Solar street lights</option><option>High mast</option><option>Solar rooftop</option><option>Distribution / electrification</option><option>Other</option></select></div>\n          <div class=\"field w3\"><label>Quantity / Units</label><input type=\"number\" name=\"energy_quantity\"></div>\n          <div class=\"field w3\"><label>Rated Power per Unit (W)</label><input type=\"number\" step=\"0.01\" name=\"watt_per_unit\"></div>\n          <div class=\"field w3\"><label>Pole / Mast Height (m)</label><input type=\"number\" step=\"0.01\" name=\"pole_height_m\"></div>\n          <div class=\"field w3\"><label>Spacing (m)</label><input type=\"number\" step=\"0.01\" name=\"spacing_m\"></div>\n          <div class=\"field w3\"><label>Solar Panel (Wp)</label><input type=\"number\" step=\"0.01\" name=\"solar_wp\"></div>\n          <div class=\"field w3\"><label>Battery Capacity / Chemistry</label><input name=\"battery_spec\"></div>\n          <div class=\"field w3\"><label>Cabling Length (m)</label><input type=\"number\" step=\"0.01\" name=\"cabling_length_m\"></div>\n          <div class=\"field w6\"><label>Technical specification / standards</label><input name=\"energy_spec\"></div>\n          <div class=\"field w6\"><label>Existing supply / pole / feeder details</label><input name=\"existing_energy_infra\"></div>\n        </div></div>\n\n        <div class=\"dynamic hidden\" id=\"type_equipment\"><div class=\"grid\">\n          <div class=\"field w3\"><label>Equipment Category</label><input name=\"equipment_category\"></div>\n          <div class=\"field w3\"><label>Quantity</label><input type=\"number\" name=\"equipment_quantity\"></div>\n          <div class=\"field w3\"><label>Unit Capacity / Rating</label><input name=\"equipment_capacity\"></div>\n          <div class=\"field w3\"><label>Benchmark Source</label><select name=\"equipment_benchmark_source\"><option>GeM</option><option>Approved rate contract</option><option>State procurement rate</option><option>Market quotation</option><option>Other</option></select></div>\n          <div class=\"field w6\"><label>Minimum technical specification (vendor-neutral)</label><textarea name=\"equipment_spec\"></textarea></div>\n          <div class=\"field w3\"><label>Warranty Requirement</label><input name=\"warranty_requirement\"></div>\n          <div class=\"field w3\"><label>Installation / commissioning included?</label><select name=\"installation_included\"><option>Yes</option><option>No</option></select></div>\n        </div></div>\n\n        <div class=\"dynamic hidden\" id=\"type_park\"><div class=\"grid\">\n          <div class=\"field w3\"><label>Total Area (m²)</label><input type=\"number\" step=\"0.01\" name=\"park_area\"></div>\n          <div class=\"field w3\"><label>Developed / Surface Area (m²)</label><input type=\"number\" step=\"0.01\" name=\"developed_area\"></div>\n          <div class=\"field w3\"><label>Track / Path Length (m)</label><input type=\"number\" step=\"0.01\" name=\"track_length\"></div>\n          <div class=\"field w3\"><label>Fencing / Boundary Length (m)</label><input type=\"number\" step=\"0.01\" name=\"fencing_length\"></div>\n          <div class=\"field w4\"><label>Sports / Play Equipment Count</label><input type=\"number\" name=\"play_equipment_count\"></div>\n          <div class=\"field w4\"><label>Lighting Units</label><input type=\"number\" name=\"park_lighting_count\"></div>\n          <div class=\"field w4\"><label>Water / Irrigation Scope</label><input name=\"park_water_scope\"></div>\n          <div class=\"field w12\"><label>Surface / equipment / landscape specification</label><textarea name=\"park_spec\"></textarea></div>\n        </div></div>\n\n        <div class=\"dynamic hidden\" id=\"type_other\"><div class=\"grid\">\n          <div class=\"field w4\"><label>Primary Measurable Unit</label><input name=\"other_primary_unit\" placeholder=\"m, m², m³, number, kW, kL etc.\"></div>\n          <div class=\"field w4\"><label>Primary Quantity</label><input type=\"number\" step=\"0.01\" name=\"other_primary_qty\"></div>\n          <div class=\"field w4\"><label>Secondary Dimensions / Capacity</label><input name=\"other_dimensions\"></div>\n          <div class=\"field w12\"><label>Technical specification sufficient to derive quantities and benchmark cost</label><textarea name=\"other_technical_spec\"></textarea></div>\n        </div></div>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <div class=\"sectionhead\"><h2>F. Detailed Estimate / BOQ — Machine-Readable Line Items</h2><div class=\"agentchips\"><span class=\"chip cost\">COST</span></div></div>\n      <div class=\"sectionbody grid\">\n        <div class=\"field w3\"><label>Applicable State / Department Schedule of Rates <span class=\"req\">*</span></label><input name=\"sor_name\" required placeholder=\"e.g., PWD SOR / CPWD DSR\"></div>\n        <div class=\"field w3\"><label>SOR Edition / Year <span class=\"req\">*</span></label><input name=\"sor_year\" required></div>\n        <div class=\"field w3\"><label>Cost Index / Escalation Factor (if applicable)</label><input name=\"cost_index\"></div>\n        <div class=\"field w3\"><label>Estimate Prepared / Checked By</label><input name=\"estimate_engineer\"></div>\n        <div class=\"tablewrap\">\n          <table id=\"boqTable\">\n            <thead><tr><th>#</th><th>SoR / Benchmark Code</th><th>Item Description & Specification</th><th>Unit</th><th>Qty</th><th>Rate ₹</th><th>Amount ₹</th><th>Rate Source</th><th>Quantity Derivation / Measurement Ref</th><th>Deviation / Site-condition Justification</th><th title=\"A composite SoR item (e.g. brick masonry per m³) or a machine hired with its operator\">Rate includes its workers?</th><th class=\"row-actions\">Action</th></tr></thead>\n            <tbody id=\"boqBody\"></tbody>\n          </table>\n        </div>\n        <div class=\"totalbar\"><button class=\"smallbtn no-print\" type=\"button\" onclick=\"addBoqRow()\">+ Add BOQ Line</button><span>Calculated BOQ Total</span><strong id=\"boqTotal\">₹0.00</strong></div>\n        <div class=\"subhead\">Labour schedule — one row per trade (workers are listed here, not among the BOQ lines). Only a day rate far above what others pay the same trade, or days beyond the work's own time, are questioned; how many workers a work needs is never judged.</div>\n        <div class=\"tablewrap\">\n          <table id=\"labourTable\" style=\"min-width:1400px\">\n            <thead><tr><th>#</th><th>Trade</th><th>Trade name (if Other)</th><th>Grade</th><th>Workers</th><th>Days each on site</th><th>Day rate ₹</th><th>Person-days</th><th>Amount ₹</th><th>What they do</th><th>BOQ lines they work on (e.g. 1, 3-5)</th><th>Rate Source</th><th class=\"row-actions\">Action</th></tr></thead>\n            <tbody id=\"labourBody\"></tbody>\n          </table>\n        </div>\n        <div class=\"totalbar\"><button class=\"smallbtn no-print\" type=\"button\" onclick=\"addLabourRow()\">+ Add Labour Row</button><span>Calculated Labour Total</span><strong id=\"labourTotal\">₹0.00</strong></div>\n        <div class=\"field w4\"><label>Non-BOQ / Lump-sum Components (₹)</label><input type=\"number\" step=\"0.01\" name=\"lumpsum_components\" oninput=\"recalcTotals()\"></div>\n        <div class=\"field w4\"><label>Permissible Charges / Contingencies / Testing (₹)</label><input type=\"number\" step=\"0.01\" name=\"other_charges\" oninput=\"recalcTotals()\"></div>\n        <div class=\"field w4\"><label>Taxes / GST Treatment</label><select name=\"tax_treatment\"><option>Included in rates</option><option>Added separately</option><option>Not applicable / exempt</option><option>To be confirmed</option></select></div>\n        <div class=\"field w4\"><label>Total Technical Estimate (₹) <span class=\"req\">*</span></label><input id=\"technicalEstimate\" type=\"number\" step=\"0.01\" name=\"technical_estimate\" required></div>\n        <div class=\"field w4\"><label>Amount Recommended / Earmarked by MP (₹) <span class=\"req\">*</span></label><input type=\"number\" step=\"0.01\" name=\"mp_recommended_amount\" required></div>\n        <div class=\"field w4\"><label>If estimate exceeds MP amount: consent / additional allocation reference</label><input name=\"mp_additional_consent_ref\"></div>\n        <div class=\"field w4\"><label>MPLADS Share Proposed (₹)</label><input type=\"number\" step=\"0.01\" name=\"mplads_share\"></div>\n        <div class=\"field w4\"><label>Other Govt / Local-body Scheme Share (₹)</label><input type=\"number\" step=\"0.01\" name=\"other_govt_share\"></div>\n        <div class=\"field w4\"><label>Other Scheme / Sanction Reference</label><input name=\"other_scheme_ref\"></div>\n        <div class=\"field w6\"><label>Major Material Sources / Lead Distances</label><textarea name=\"major_material_sources\" placeholder=\"Material — source — lead distance — basis/document\"></textarea></div>\n        <div class=\"field w6\"><label>Rate deviation notes</label><textarea name=\"rate_deviation_notes\" placeholder=\"Only evidence-based deviations from official/benchmark rates.\"></textarea></div>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <div class=\"sectionhead\"><h2>G. Timeline, Milestones & Time-Rule Inputs</h2><div class=\"agentchips\"><span class=\"chip time\">TIME / RULES</span><span class=\"chip site\">SITE</span></div></div>\n      <div class=\"sectionbody grid\">\n        <div class=\"field w3\"><label>Proposed Sanction Decision <span class=\"req\">*</span></label><select name=\"sanction_decision\" required><option value=\"\">Select</option><option>Sanction</option><option>Reject</option><option>Return for clarification</option></select></div>\n        <div class=\"field w3\"><label>Sanction / Decision Date</label><input type=\"date\" name=\"sanction_date\"></div>\n        <div class=\"field w3\"><label>Expected Work Start Date <span class=\"req\">*</span></label><input type=\"date\" name=\"expected_start_date\" required></div>\n        <div class=\"field w3\"><label>Agency Estimated Duration (days) <span class=\"req\">*</span></label><input type=\"number\" name=\"estimated_duration_days\" required></div>\n        <div class=\"field w3\"><label>Expected Completion Date <span class=\"req\">*</span></label><input type=\"date\" name=\"expected_completion_date\" required></div>\n        <div class=\"field w3\"><label>Estimated Working Days</label><input type=\"number\" name=\"working_days\"></div>\n        <div class=\"field w3\"><label>Expected Lost / Non-working Days</label><input type=\"number\" name=\"lost_days\"></div>\n        <div class=\"field w3\"><label>Why lost days are expected</label><input name=\"lost_days_reason\" placeholder=\"monsoon, curing, access, approvals etc.\"></div>\n        <div class=\"field w6\"><label>Justification if estimated completion exceeds one year</label><textarea name=\"over_one_year_justification\"></textarea></div>\n        <div class=\"field w6\"><label>Construction / engineering minimum-time constraints</label><textarea name=\"minimum_time_constraints\" placeholder=\"Curing, formwork, procurement, commissioning, staged testing, seasonal windows, etc.\"></textarea></div>\n\n        <div class=\"subhead\">Planned milestones — used later to compare monthly site evidence with promised progress</div>\n        <div class=\"tablewrap\">\n          <table id=\"milestoneTable\" style=\"min-width:700px\"><thead><tr><th>#</th><th>Milestone / Stage</th><th>Planned Date</th><th>Expected Physical %</th><th>Evidence expected at site</th><th class=\"row-actions\">Action</th></tr></thead><tbody id=\"milestoneBody\"></tbody></table>\n        </div>\n        <div class=\"field w12 no-print\"><button class=\"smallbtn\" type=\"button\" onclick=\"addMilestoneRow()\">+ Add Milestone</button></div>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <div class=\"sectionhead\"><h2>H. Guideline Eligibility, Clearances & Sanction Preconditions</h2><div class=\"agentchips\"><span class=\"chip time\">RULES</span></div></div>\n      <div class=\"sectionbody grid\">\n        <div class=\"checkgrid\">\n          <label class=\"check\"><input type=\"checkbox\" name=\"durable_public_asset\"><span>Creates/strengthens a durable public asset for public good.</span></label>\n          <label class=\"check\"><input type=\"checkbox\" name=\"no_om_funding\"><span>Request is not for recurring operation & maintenance expenditure.</span></label>\n          <label class=\"check\"><input type=\"checkbox\" name=\"not_residential\"><span>Not construction of a residential building.</span></label>\n          <label class=\"check\"><input type=\"checkbox\" name=\"not_private_commercial\"><span>Not a commercial/private establishment or private-benefit work.</span></label>\n          <label class=\"check\"><input type=\"checkbox\" name=\"no_land_acquisition\"><span>No land acquisition / land compensation is funded from MPLADS.</span></label>\n          <label class=\"check\"><input type=\"checkbox\" name=\"not_reimbursement\"><span>Not reimbursement for a completed/partly completed/ongoing work or prior purchase.</span></label>\n          <label class=\"check\"><input type=\"checkbox\" name=\"no_csr_pooling\"><span>No pooling of MPLADS funds with CSR funds.</span></label>\n          <label class=\"check\"><input type=\"checkbox\" name=\"not_religious\"><span>Not a religious work / worship premises / land owned by religious faith/group.</span></label>\n          <label class=\"check\"><input type=\"checkbox\" name=\"not_welcome_gate\"><span>Not construction of a Swagat Dwar / Welcome Gate.</span></label>\n          <label class=\"check\"><input type=\"checkbox\" name=\"authorized_colony\"><span>Site is not in an unauthorized colony / unapproved location.</span></label>\n          <label class=\"check\"><input type=\"checkbox\" name=\"not_named_person\"><span>Asset is not proposed to be named after a living/dead person.</span></label>\n          <label class=\"check\"><input type=\"checkbox\" name=\"accessibility_considered\"><span>Accessibility for persons with disabilities has been considered wherever feasible.</span></label>\n        </div>\n        <div class=\"field w4\"><label>Estimated Amount below ₹2.5 lakh?</label><select name=\"below_min_threshold\"><option>No</option><option>Yes</option></select></div>\n        <div class=\"field w8\"><label>If yes, recorded public-benefit justification</label><input name=\"below_threshold_justification\"></div>\n        <div class=\"field w4\"><label>User Agency O&M Undertaking Status <span class=\"req\">*</span></label><select name=\"om_undertaking_status\" required><option value=\"\">Select</option><option>Obtained</option><option>Pending</option><option>Not applicable</option></select></div>\n        <div class=\"field w4\"><label>O&M Undertaking Reference</label><input name=\"om_undertaking_ref\"></div>\n        <div class=\"field w4\"><label>Technical Feasibility Certificate / Note Ref.</label><input name=\"technical_feasibility_ref\"></div>\n        <div class=\"field w4\"><label>Technical Sanction No. / Ref.</label><input name=\"technical_sanction_ref\"></div>\n        <div class=\"field w4\"><label>Administrative / Financial Sanction Ref.</label><input name=\"admin_financial_sanction_ref\"></div>\n        <div class=\"field w4\"><label>Open / Transparent Procurement Method Planned</label><select name=\"procurement_method\"><option value=\"\">Select</option><option>Open tender / e-procurement</option><option>Rate contract</option><option>GeM</option><option>Departmental execution as permitted</option><option>Other approved process</option></select></div>\n        <div class=\"field w4\"><label>MPLADS Plaque / Disclosure Provision Included?</label><select name=\"plaque_provision\"><option>Yes</option><option>No / not applicable</option><option>To be added</option></select></div>\n        <div class=\"field w4\"><label>Public-use / Handover Plan after Completion</label><input name=\"handover_plan\"></div>\n\n        <div class=\"subhead\">Statutory / Regulatory Clearances — mark what applies and record evidence</div>\n        <div class=\"tablewrap\"><table style=\"min-width:800px\"><thead><tr><th>Clearance / NOC</th><th>Applicable?</th><th>Status</th><th>Authority</th><th>Reference No. / Date</th></tr></thead><tbody>\n          <tr><td>Land ownership / possession</td><td><select name=\"land_clearance_app\"><option>Yes</option><option>No</option></select></td><td><select name=\"land_clearance_status\"><option>Obtained</option><option>Pending</option><option>NA</option></select></td><td><input name=\"land_clearance_authority\"></td><td><input name=\"land_clearance_ref\"></td></tr>\n          <tr><td>Local body / building / development permission</td><td><select name=\"local_clearance_app\"><option>No</option><option>Yes</option></select></td><td><select name=\"local_clearance_status\"><option>NA</option><option>Obtained</option><option>Pending</option></select></td><td><input name=\"local_clearance_authority\"></td><td><input name=\"local_clearance_ref\"></td></tr>\n          <tr><td>Environment / pollution control</td><td><select name=\"env_clearance_app\"><option>No</option><option>Yes</option></select></td><td><select name=\"env_clearance_status\"><option>NA</option><option>Obtained</option><option>Pending</option></select></td><td><input name=\"env_clearance_authority\"></td><td><input name=\"env_clearance_ref\"></td></tr>\n          <tr><td>Forest / wildlife</td><td><select name=\"forest_clearance_app\"><option>No</option><option>Yes</option></select></td><td><select name=\"forest_clearance_status\"><option>NA</option><option>Obtained</option><option>Pending</option></select></td><td><input name=\"forest_clearance_authority\"></td><td><input name=\"forest_clearance_ref\"></td></tr>\n          <tr><td>Railway / National Highway / PWD / road-cutting</td><td><select name=\"road_clearance_app\"><option>No</option><option>Yes</option></select></td><td><select name=\"road_clearance_status\"><option>NA</option><option>Obtained</option><option>Pending</option></select></td><td><input name=\"road_clearance_authority\"></td><td><input name=\"road_clearance_ref\"></td></tr>\n          <tr><td>Utility shifting / electricity / water / telecom</td><td><select name=\"utility_clearance_app\"><option>No</option><option>Yes</option></select></td><td><select name=\"utility_clearance_status\"><option>NA</option><option>Obtained</option><option>Pending</option></select></td><td><input name=\"utility_clearance_authority\"></td><td><input name=\"utility_clearance_ref\"></td></tr>\n          <tr><td>Fire / safety / structural / health-specific clearance</td><td><select name=\"safety_clearance_app\"><option>No</option><option>Yes</option></select></td><td><select name=\"safety_clearance_status\"><option>NA</option><option>Obtained</option><option>Pending</option></select></td><td><input name=\"safety_clearance_authority\"></td><td><input name=\"safety_clearance_ref\"></td></tr>\n          <tr><td>Other project-specific clearance</td><td><select name=\"other_clearance_app\"><option>No</option><option>Yes</option></select></td><td><select name=\"other_clearance_status\"><option>NA</option><option>Obtained</option><option>Pending</option></select></td><td><input name=\"other_clearance_authority\"></td><td><input name=\"other_clearance_ref\"></td></tr>\n        </tbody></table></div>\n        <div class=\"field w6\"><label>Site changed from MP recommendation?</label><select name=\"site_changed\"><option>No</option><option>Yes, before sanction with MP concurrence</option><option>Yes, without concurrence</option></select></div>\n        <div class=\"field w6\"><label>If changed, MP concurrence reference and reason</label><input name=\"site_change_ref\"></div>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <div class=\"sectionhead\"><h2>I. Site Progress Baseline & Evidence Plan</h2><div class=\"agentchips\"><span class=\"chip site\">NIDHILENS</span><span class=\"chip time\">TIME</span><span class=\"chip dup\">DUPLICATE</span></div></div>\n      <div class=\"sectionbody grid\">\n        <div class=\"field w4\"><label>Baseline capture required before work starts? <span class=\"req\">*</span></label><select name=\"baseline_capture_required\" required><option>Yes</option><option>No — justify</option></select></div>\n        <div class=\"field w4\"><label>Planned Number of Fixed Viewpoints <span class=\"req\">*</span></label><input type=\"number\" name=\"fixed_viewpoint_count\" min=\"1\" required></div>\n        <div class=\"field w4\"><label>Monthly Capture Responsible Officer / Role</label><input name=\"capture_responsible_role\"></div>\n        <div class=\"field w6\"><label>Site zone / viewpoint plan reference</label><input name=\"viewpoint_plan_ref\" placeholder=\"Map drawing / zone IDs / camera viewpoint plan\"></div>\n        <div class=\"field w6\"><label>Baseline video target date</label><input type=\"date\" name=\"baseline_video_date\"></div>\n        <div class=\"field w4\"><label>Capture Frequency</label><select name=\"capture_frequency\"><option>Monthly</option><option>More frequent for critical stages</option></select></div>\n        <div class=\"field w4\"><label>Random independent check enabled?</label><select name=\"random_check_enabled\"><option>Yes</option><option>No</option></select></div>\n        <div class=\"field w4\"><label>Completion capture required?</label><select name=\"completion_capture_required\"><option>Yes</option><option>No</option></select></div>\n        <div class=\"field w12\"><label>What must be visible to prove completion for this work?</label><textarea name=\"completion_evidence_definition\" placeholder=\"Define measurable visible evidence: full road length/width, building functional spaces, tank/pipeline/fixtures, installed units, etc.\"></textarea></div>\n        <div class=\"field w6\"><label>Pre-existing asset / condition that must be shown at baseline</label><textarea name=\"baseline_existing_condition\"></textarea></div>\n        <div class=\"field w6\"><label>Site-specific anti-substitution notes</label><textarea name=\"anti_substitution_notes\" placeholder=\"Distinctive landmarks, plaque location, boundaries, alignment, fixed structures, etc.\"></textarea></div>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <div class=\"sectionhead\"><h2>J. Agent Data Readiness — Pre-Sanction Gate</h2><small>Completeness only; this is not a fraud score</small></div>\n      <div class=\"sectionbody\">\n        <div class=\"readiness\">\n          <div class=\"readycard\"><b>Cost Agent</b><span>Needs measurable scope, BOQ line items, quantities, official/benchmark rate basis, labour by trade (workers, days, day rate), project geometry and site-condition facts.</span></div>\n          <div class=\"readycard\"><b>Duplicate Agent</b><span>Needs reliable geometry, new/continuation/rebuild status, prior/related work IDs and whole-project/package relationships.</span></div>\n          <div class=\"readycard\"><b>Time & Rules Agent</b><span>Needs recommendation/receipt/sanction dates, project kind & size, realistic duration, milestone plan, eligibility facts and clearances.</span></div>\n          <div class=\"readycard\"><b>NidhiLens (Fine-Tuned Site Progress Model)</b><span>Needs baseline capture plan, fixed viewpoints/zones, measurable completion definition, site geometry and later monthly evidence.</span></div>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <div class=\"sectionhead\"><h2>K. Certification, Verification & Data Lock</h2><small>Human decision remains with the competent authority</small></div>\n      <div class=\"sectionbody\">\n        <div class=\"inline\"><input type=\"checkbox\" name=\"certify_accuracy\" id=\"certifyAccuracy\"><label for=\"certifyAccuracy\" style=\"margin:0\">I certify that measurements, quantities, rates, site coordinates, related-work declarations and uploaded references are based on records / field verification and are not placeholders.</label></div>\n        <div class=\"inline\" style=\"margin-top:8px\"><input type=\"checkbox\" name=\"consent_agent_verification\" id=\"consentVerify\"><label for=\"consentVerify\" style=\"margin:0\">I understand NidhiNetra will independently verify these entries against official rates, prior works, map geometry, dates and later site evidence; a declaration does not override contradictory evidence.</label></div>\n        <div class=\"signature\">\n          <div class=\"sigbox\"><b>Prepared by — Implementing Agency / Engineer</b>Name: ___________________________<br><br>Designation: ____________________<br><br>Date / Digital Signature: __________</div>\n          <div class=\"sigbox\"><b>Technical Verification</b>Name: ___________________________<br><br>Designation: ____________________<br><br>Date / Digital Signature: __________</div>\n          <div class=\"sigbox\"><b>Implementing District Authority — Sanction Decision</b>Name: ___________________________<br><br>Decision: _______________________<br><br>Date / Digital Signature: __________</div>\n        </div>\n      </div>\n    </section>\n  </form>\n\n  <div class=\"footer\"><span>NidhiNetra prototype form — structured pre-sanction evidence capture for agent-ready analysis.</span><span>Print layout is intentionally compact and audit-friendly.</span></div>\n</div>\n</div>\n\n<script>\nconst form = document.getElementById('nidhinetraForm');\nfunction uid(){return 'DRI-' + new Date().toISOString().slice(0,10).replaceAll('-','') + '-' + Math.random().toString(36).slice(2,7).toUpperCase()}\nfunction q(name){return form.elements[name]}\n\nfunction showDynamicType(){\n  const v = document.getElementById('workType').value;\n  document.getElementById('defaultTypeHelp').style.display = v ? 'none' : 'block';\n  ['road','building','water','drainage','energy','equipment','park','other'].forEach(x=>document.getElementById('type_'+x).classList.toggle('hidden',x!==v));\n  document.getElementById('linearGeo').style.display = ['road','water','drainage'].includes(v) ? 'block' : 'none';\n}\nfunction toggleTrustFields(){\n  const v=document.getElementById('beneficiaryType').value;\n  document.getElementById('trustFields').classList.toggle('hidden',!['Registered Society / Trust','Cooperative Society','Bar Association'].includes(v));\n}\nfunction toggleLargerProject(){document.getElementById('largerProjectFields').classList.toggle('hidden',document.getElementById('largerProject').value!=='Yes')}\n\nfunction captureGeo(which){\n  const alertBox=document.getElementById('alertBox');\n  if(!navigator.geolocation){showAlert('This browser does not support geolocation.', false);return;}\n  navigator.geolocation.getCurrentPosition(pos=>{\n    const {latitude,longitude,accuracy}=pos.coords; const t=new Date(pos.timestamp).toLocaleString();\n    if(which==='primary'){\n      lat.value=latitude.toFixed(7); lon.value=longitude.toFixed(7); acc.value=accuracy.toFixed(1); geoTime.value=t;\n      mapLink.innerHTML=`Map check: <a target=\"_blank\" href=\"https://www.openstreetmap.org/?mlat=${latitude}&mlon=${longitude}#map=18/${latitude}/${longitude}\">open captured point</a>`;\n    }else if(which==='start'){\n      startLat.value=latitude.toFixed(7); startLon.value=longitude.toFixed(7); startAcc.value=accuracy.toFixed(1); startTime.value=t;\n    }else{\n      endLat.value=latitude.toFixed(7); endLon.value=longitude.toFixed(7); endAcc.value=accuracy.toFixed(1); endTime.value=t;\n    }\n    showAlert(`Location captured. Reported GPS accuracy: ±${accuracy.toFixed(1)} m.`, true);\n  },err=>showAlert('Location capture failed: '+err.message+' — browsers normally require HTTPS or localhost and location permission.', false),{enableHighAccuracy:true,timeout:15000,maximumAge:0});\n}\n\n// rows keep their number (BOQ lines are referred to by it from the labour schedule): a new row\n// takes the next number after the highest in the table\nfunction nextRow(tbody){return Math.max(0,...[...tbody.children].map(tr=>Number(tr.dataset.n)||0))+1}\nconst SOURCES=['State/Dept SoR','CPWD/standard schedule','District recent rates','GeM / rate contract','Approved quotation','Other benchmark'];\nconst TRADES=[['beldar','Beldar / mazdoor','unskilled'],['helper','Helper','unskilled'],['chowkidar','Chowkidar / watchman','unskilled'],['mate','Mate (gang leader)','semi_skilled'],['mason','Mason / mistri','skilled'],['carpenter','Carpenter','skilled'],['bar_bender','Bar bender','skilled'],['painter','Painter','skilled'],['plumber','Plumber','skilled'],['electrician','Electrician','skilled'],['welder','Welder / fabricator','skilled'],['driver','Driver','skilled'],['operator','Machine operator','highly_skilled'],['supervisor','Supervisor / foreman','highly_skilled'],['other','Other (write its name and grade)','']];\nconst GRADES=[['unskilled','Unskilled'],['semi_skilled','Semi-skilled'],['skilled','Skilled'],['highly_skilled','Highly skilled']];\nfunction addBoqRow(data={}){\n  const tbody=document.getElementById('boqBody'); const n=nextRow(tbody); const tr=document.createElement('tr'); tr.dataset.n=n;\n  tr.innerHTML=`<td class=\"rownum\">${n}</td><td><input name=\"boq_code_${n}\" value=\"${esc(data.code||'')}\"></td><td><input name=\"boq_desc_${n}\" value=\"${esc(data.desc||'')}\"></td><td><input name=\"boq_unit_${n}\" value=\"${esc(data.unit||'')}\"></td><td><input type=\"number\" step=\"0.0001\" name=\"boq_qty_${n}\" value=\"${esc(data.qty||'')}\" oninput=\"recalcTotals()\"></td><td><input type=\"number\" step=\"0.01\" name=\"boq_rate_${n}\" value=\"${esc(data.rate||'')}\" oninput=\"recalcTotals()\"></td><td class=\"money amount\">₹0.00</td><td><select name=\"boq_source_${n}\"><option>State/Dept SoR</option><option>CPWD/standard schedule</option><option>District recent rates</option><option>GeM / rate contract</option><option>Approved quotation</option><option>Other benchmark</option></select></td><td><input name=\"boq_measure_ref_${n}\" value=\"${esc(data.measure||'')}\"></td><td><input name=\"boq_just_${n}\" value=\"${esc(data.just||'')}\"></td><td style=\"text-align:center\"><input type=\"checkbox\" name=\"boq_inclab_${n}\"></td><td class=\"row-actions\"><button type=\"button\" class=\"smallbtn danger\" onclick=\"removeRow(this)\">Remove</button></td>`;\n  tbody.appendChild(tr); recalcTotals();\n}\nfunction addLabourRow(){\n  const tbody=document.getElementById('labourBody'); const n=nextRow(tbody); const tr=document.createElement('tr'); tr.dataset.n=n;\n  tr.innerHTML=`<td class=\"rownum\">${n}</td><td><select name=\"lab_trade_${n}\" onchange=\"tradeGrade(this,${n})\"><option value=\"\">— choose —</option>${TRADES.map(t=>`<option value=\"${t[0]}\">${t[1]}</option>`).join('')}</select></td><td><input name=\"lab_name_${n}\"></td><td><select name=\"lab_grade_${n}\"><option value=\"\">—</option>${GRADES.map(g=>`<option value=\"${g[0]}\">${g[1]}</option>`).join('')}</select></td><td><input type=\"number\" min=\"1\" step=\"1\" name=\"lab_workers_${n}\" oninput=\"recalcTotals()\"></td><td><input type=\"number\" min=\"0.5\" step=\"0.5\" name=\"lab_days_${n}\" oninput=\"recalcTotals()\"></td><td><input type=\"number\" step=\"0.01\" name=\"lab_rate_${n}\" oninput=\"recalcTotals()\"></td><td class=\"money pdays\">0</td><td class=\"money amount\">₹0.00</td><td><input name=\"lab_task_${n}\" placeholder=\"e.g. brick and plaster work\"></td><td><input name=\"lab_lines_${n}\"></td><td><select name=\"lab_source_${n}\">${SOURCES.concat(['Minimum wages notification']).map(o=>`<option>${o}</option>`).join('')}</select></td><td class=\"row-actions\"><button type=\"button\" class=\"smallbtn danger\" onclick=\"removeRow(this)\">Remove</button></td>`;\n  tbody.appendChild(tr); recalcTotals();\n}\n// a listed trade fills its own grade; \"Other\" asks for it\nfunction tradeGrade(sel,n){const t=TRADES.find(x=>x[0]===sel.value); if(t&&t[2]) q('lab_grade_'+n).value=t[2]}\nfunction addMilestoneRow(){\n  const tbody=document.getElementById('milestoneBody'); const n=tbody.children.length+1; const tr=document.createElement('tr');\n  tr.innerHTML=`<td class=\"rownum\">${n}</td><td><input name=\"milestone_name_${n}\"></td><td><input type=\"date\" name=\"milestone_date_${n}\"></td><td><input type=\"number\" min=\"0\" max=\"100\" name=\"milestone_pct_${n}\"></td><td><input name=\"milestone_evidence_${n}\"></td><td class=\"row-actions\"><button type=\"button\" class=\"smallbtn danger\" onclick=\"removeRow(this)\">Remove</button></td>`;\n  tbody.appendChild(tr);\n}\nfunction removeRow(btn){btn.closest('tr').remove(); renumberTables(); recalcTotals()}\nfunction renumberTables(){['milestoneBody'].forEach(id=>[...document.getElementById(id).children].forEach((tr,i)=>tr.querySelector('.rownum').textContent=i+1))}\nfunction recalcTotals(){\n  let total=0; [...document.querySelectorAll('#boqBody tr')].forEach(tr=>{const nums=tr.querySelectorAll('input[type=number]'); const qty=parseFloat(nums[0]?.value||0), rate=parseFloat(nums[1]?.value||0); const amt=qty*rate; tr.querySelector('.amount').textContent='₹'+amt.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}); total+=amt;});\n  document.getElementById('boqTotal').textContent='₹'+total.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});\n  let labour=0; [...document.querySelectorAll('#labourBody tr')].forEach(tr=>{const nums=tr.querySelectorAll('input[type=number]'); const pd=parseFloat(nums[0]?.value||0)*parseFloat(nums[1]?.value||0), amt=pd*parseFloat(nums[2]?.value||0); tr.querySelector('.pdays').textContent=pd.toLocaleString('en-IN'); tr.querySelector('.amount').textContent='₹'+amt.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}); labour+=amt;});\n  document.getElementById('labourTotal').textContent='₹'+labour.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});\n  const lump=parseFloat(q('lumpsum_components')?.value||0), other=parseFloat(q('other_charges')?.value||0); if(q('technical_estimate')) q('technical_estimate').value=(total+labour+lump+other).toFixed(2);\n}\nfunction esc(s){return String(s).replace(/[&<>'\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',\"'\":'&#39;','\"':'&quot;'}[c]))}\n\nfunction serialize(){\n  const fd=new FormData(form); const out={}; for(const [k,v] of fd.entries()){if(out[k]!==undefined){if(!Array.isArray(out[k])) out[k]=[out[k]];out[k].push(v)}else out[k]=v}\n  [...form.querySelectorAll('input[type=checkbox]')].forEach(cb=>out[cb.name]=cb.checked);\n  out.__meta={form_version:'PSWIF v1.1',work_id:document.getElementById('workIdDisplay').textContent,exported_at:new Date().toISOString(),boq_calculated_total:document.getElementById('boqTotal').textContent,labour_calculated_total:document.getElementById('labourTotal').textContent};\n  return out;\n}\nfunction restore(data){\n  for(const [k,v] of Object.entries(data)){if(k==='__meta')continue; const el=form.elements[k]; if(!el)continue; if(el.type==='checkbox') el.checked=!!v; else el.value=Array.isArray(v)?v[0]:v}\n  if(data.__meta?.work_id) document.getElementById('workIdDisplay').textContent=data.__meta.work_id;\n  showDynamicType(); toggleTrustFields(); toggleLargerProject(); recalcTotals();\n}\nfunction saveDraft(){\n  if(document.getElementById('workIdDisplay').textContent==='Auto on save') document.getElementById('workIdDisplay').textContent=uid();\n  localStorage.setItem('nidhinetra_pswif_draft',JSON.stringify(serialize())); document.getElementById('headerStatus').textContent='DRAFT SAVED'; showAlert('Draft saved in this browser.',true)\n}\nfunction loadDraft(){const raw=localStorage.getItem('nidhinetra_pswif_draft'); if(!raw){showAlert('No saved draft found in this browser.',false);return} restore(JSON.parse(raw)); showAlert('Saved draft loaded.',true)}\nfunction clearDraft(){if(!confirm('Clear this form and saved draft?'))return; localStorage.removeItem('nidhinetra_pswif_draft'); form.reset(); document.getElementById('workIdDisplay').textContent='Auto on save'; document.getElementById('headerStatus').textContent='DRAFT'; document.getElementById('boqBody').innerHTML='';document.getElementById('labourBody').innerHTML='';document.getElementById('milestoneBody').innerHTML=''; addBoqRow();addBoqRow();addBoqRow();addLabourRow();addLabourRow();addMilestoneRow();addMilestoneRow();addMilestoneRow();showDynamicType();toggleTrustFields();toggleLargerProject();recalcTotals();}\nfunction validateForm(){\n  const missing=[...form.querySelectorAll('[required]')].filter(el=>!String(el.value).trim());\n  // dynamic checks\n  const wt=document.getElementById('workType').value;\n  if(['road','water','drainage'].includes(wt)){['startLat','startLon','endLat','endLon'].forEach(id=>{const e=document.getElementById(id); if(!e.value) missing.push(e)})}\n  const boqHas=[...document.querySelectorAll('#boqBody tr')].some(tr=>{const ins=tr.querySelectorAll('input');return (ins[1]?.value||'').trim() && parseFloat(ins[3]?.value||0)>0 && parseFloat(ins[4]?.value||0)>0});\n  // a labour row is a trade with its workers, days, day rate and what they do; \"Other\" names itself and its grade\n  const labourGaps=[...document.querySelectorAll('#labourBody tr')].filter(tr=>{const n=tr.dataset.n, v=k=>String(q(k+'_'+n)?.value||'').trim(); const used=['lab_trade','lab_workers','lab_days','lab_rate','lab_task'].some(k=>v(k)); return used && (!v('lab_trade')||!(parseFloat(v('lab_workers'))>=1)||!(parseFloat(v('lab_days'))>0)||!(parseFloat(v('lab_rate'))>0)||v('lab_task').split(/\\s+/).length<2||(v('lab_trade')==='other'&&(!v('lab_name')||!v('lab_grade'))))}).map(tr=>tr.dataset.n);\n  if(!boqHas){showAlert('Required-data check: add at least one valid BOQ line with description, quantity and rate.',false)}\n  else if(labourGaps.length){showAlert(`Labour row ${labourGaps.join(', ')}: give the trade, workers, days each, day rate and what they do (Other: its name and grade).`,false)}\n  else if(missing.length){missing.forEach(e=>e.style.borderColor='#b42318'); showAlert(`Required-data check: ${missing.length} required field(s) are still incomplete.`,false)}\n  else{[...form.querySelectorAll('[required]')].forEach(e=>e.style.borderColor=''); document.getElementById('statusDot').style.background='#16a34a'; document.getElementById('readinessText').textContent='Core mandatory fields complete — ready for agent pre-check'; showAlert('Core required-data check passed. Agent-specific rules can now run on structured data.',true)}\n}\nfunction downloadJSON(){\n  if(document.getElementById('workIdDisplay').textContent==='Auto on save') document.getElementById('workIdDisplay').textContent=uid();\n  const blob=new Blob([JSON.stringify(serialize(),null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=document.getElementById('workIdDisplay').textContent+'_presanction.json';a.click();URL.revokeObjectURL(a.href)\n}\nfunction showAlert(msg,ok){const b=document.getElementById('alertBox');b.className='alert show'+(ok?' ok':'');b.textContent=msg;setTimeout(()=>b.classList.remove('show'),7000)}\n\naddBoqRow();addBoqRow();addBoqRow();addLabourRow();addLabourRow();addMilestoneRow();addMilestoneRow();addMilestoneRow();\n\n// On a phone each table row is a card (CSS below 560px): every cell names its column from the\n// table's header, and rows added later get their names too.\nfunction labelCells(table){\n  const heads=[...table.querySelectorAll('thead th')].map(th=>th.textContent.trim());\n  table.querySelectorAll('tbody tr').forEach(tr=>[...tr.children].forEach((td,i)=>{if(heads[i]&&!td.dataset.label)td.dataset.label=heads[i]}));\n}\ndocument.querySelectorAll('.tablewrap table').forEach(t=>{labelCells(t);new MutationObserver(()=>labelCells(t)).observe(t.tBodies[0],{childList:true})});\n</script>\n</body>\n</html>\n";

